import{d,C as a,o as g,c as p,a3 as e,E as s,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十一章","description":"《正易心法》第十一章——至于六子，即是阴阳：偏陂反侧是不平之名；六子象众人与万物，然破体炼之，纯体乃成。","frontmatter":{"title":"正易心法·第十一章","description":"《正易心法》第十一章——至于六子，即是阴阳：偏陂反侧是不平之名；六子象众人与万物，然破体炼之，纯体乃成。","category":"guide","aliases":["正易心法第十一章","偏陂反侧","破体炼之纯体乃成"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-11.md","filePath":"yijing/zheng-yi-xin-fa/chapter-11.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-11.md"},x=d({...c,setup(u){const o=[{id:"z11-01",label:"一、六子即是阴阳",showLabel:!0,sentences:[["至于六子，即是阴阳。",{text:"偏陂",glossary:"pianpo"},"反侧，不平之名。"]],note:["至于六子卦，也是阴阳——但偏斜不正、反侧不安，是不平衡状态的名称。（注意第十章与本章的对举：乾坤「即是阴阳」，六子「也是阴阳」——**同为阴阳，差别在纯与驳、平与不平**。六子不是另一种东西，而是同一种阴阳的偏态。）"]},{id:"z11-02",label:"二、一失健顺",showLabel:!0,sentences:[["乾健坤顺，阴阳之纯气也。一失健顺，则不平之气作，而六子生，观画象可知。"]],note:["乾的刚健、坤的柔顺，是阴阳的纯粹之气；一旦失去这刚健柔顺，不平之气便兴起，六子于是产生——观察卦画便可知晓。（六子各「偏」一处：震阳偏于下（躁）、巽阴伏于下（柔）、坎阳陷于中（险）、离阴附于中（虚）、艮阳止于上（滞）、兑阴浮于上（浮）。**没有一个是平衡的——这就是「不平之名」的具体含义。**）"]},{id:"z11-03",label:"三、庄子言阴阳错行",showLabel:!0,sentences:[["《庄子》曰：“阴阳",{text:"错行",glossary:"cuoxing"},"，天地大骇，有雷有霆，水中有火，",{text:"乃焚乃块",glossary:"naifennaikuai"},"。”正谓此耳。"]],note:["《庄子》说：「阴阳交错运行，天地大为震骇，于是有雷有霆，水中有火，乃至焚烧崩裂。」说的正是这个道理。（妙处在于六子几乎都在这句话里：有雷有霆＝震、水中有火＝坎离相激、乃焚＝离、乃块＝艮；巽（风）、兑（泽）虽未明点，也在其中。这是本书第二次引道家，且与第十章恰好成对——**《老子》「得一」说纯粹（乾坤），《庄子》「错行」说驳杂（六子）**。麻衣用道家的两个极端，夹住了全书的核心张力。）"]},{id:"z11-04",label:"四、六子非圣贤比",showLabel:!0,sentences:[["由是六子非圣贤比，特众人与万物而已。"]],note:["因此六子不能与圣贤相比，不过是众人与万物的象征而已。（这里有一个重要的平等性：**圣人（乾）、贤人（坤）、众人（六子）、万物（六子）都是阴阳的表现形式，只是纯粹程度不同。** 麻衣没说众人是「坏的」，也没说万物是「低等的」，只是说「偏陂，不平衡」——而不平衡，可以通过「炼」来改变。这与儒家「人皆可以为尧舜」暗合：**差别不在本质，在于是否经历了「炼」。**）"]},{id:"z11-05",label:"五、破体炼之",showLabel:!0,sentences:[["然由破体",{text:"炼",glossary:"lian"},"之，纯体乃成。"]],note:["然而经由破体的磨炼，纯体才能成就。（这是《正易心法》中唯一一句直接谈修养工夫的话，也是本章的分量所在：**不是叫你逃离偏陂，不是叫你假装自己是乾坤，而是说——正是在偏陂的磨炼中，纯体才能成就。破体不是悲剧，是必经之路。**「炼」字在陈抟一脉有内丹背景：矿石（驳）→ 冶炼 → 纯金（纯）；对应内丹的「炼精化气、炼气化神、炼神还虚」，即六子（坎离为核心）→ 坎离交媾 → 乾坤复原，也就是「后天返先天」。）"]}],i=[{id:"pianpo",term:"偏陂",pinyin:"piān pō",meaning:"偏斜不正。阴阳不纯，有所偏倚——六子各偏一处，故为「不平之名」。"},{id:"cuoxing",term:"错行",pinyin:"cuò xíng",meaning:"交错运行。语出《庄子》，描述阴阳失序的状态，对应六子。"},{id:"naifennaikuai",term:"乃焚乃块",pinyin:"nǎi fén nǎi kuài",meaning:"焚烧与崩裂。焚为离火之象，块为艮土崩裂之象。"},{id:"lian",term:"炼",pinyin:"liàn",meaning:"锻炼、提纯。「破体炼之，纯体乃成」——不逃离偏陂，而在偏陂中炼。"}];return(b,t)=>{const r=a("DaoTextReading"),l=a("DaoKeywordCards");return g(),p("div",null,[t[0]||(t[0]=e("",21)),s(r,{colophon:"偏陂反侧 · 不平之名 · 阴阳错行 · 破体炼之",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十一章原文",sections:o,glossary:i}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"偏陂反侧",pinyin:["piān","pō"],meaning:"偏斜不正、翻转不安。六子各偏一处：震躁、巽柔、坎险、离虚、艮滞、兑浮——皆「不平之名」。"},{term:"不平之气作",pinyin:["bù","píng"],meaning:"失去纯粹健顺之后，不平衡的气兴起，六子由此而生。观卦画便可知晓。"},{term:"阴阳错行",pinyin:["cuò","xíng"],meaning:"《庄子》语。六子几乎都在这一句里：雷霆为震、水中有火为坎离、乃焚为离、乃块为艮。"},{term:"破体炼之",pinyin:["pò","tǐ"],meaning:"全书唯一的工夫论：不逃离偏陂，不假装是乾坤，而是在偏陂的磨炼中成就纯体。"},{term:"炼（内丹背景）",pinyin:["liàn"],meaning:"矿石（驳）→ 纯金（纯）；内丹「炼精化气、炼气化神、炼神还虚」即六子坎离交媾、后天返先天。"}]}),t[3]||(t[3]=e("",25))])}}});export{y as __pageData,x as default};
